const VOX_API_URL = import.meta.env.VITE_VOX_API_URL ?? ''

async function voxFetch<T>(path: string, options?: RequestInit): Promise<T> {
  const res = await fetch(`${VOX_API_URL}${path}`, {
    headers: { 'Content-Type': 'application/json' },
    ...options,
  })
  if (!res.ok) throw new Error(`Vox API error: ${res.status}`)
  return res.json() as Promise<T>
}

export const voxClient = { fetch: voxFetch }
